CREATE TABLE IF NOT EXISTS migrations (version integer PRIMARY KEY, applied_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS settings (id integer PRIMARY KEY CHECK(id=1), data jsonb NOT NULL);
CREATE TABLE IF NOT EXISTS prospects (id uuid PRIMARY KEY, data jsonb NOT NULL, status text NOT NULL DEFAULT 'NEW', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS audits (id uuid PRIMARY KEY, prospect_id uuid NOT NULL REFERENCES prospects(id), idempotency_key text NOT NULL UNIQUE, version integer NOT NULL, status text NOT NULL DEFAULT 'QUEUED', stage text NOT NULL DEFAULT 'QUEUED', attempts integer NOT NULL DEFAULT 0, config jsonb NOT NULL, error jsonb, started_at timestamptz, completed_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), heartbeat_at timestamptz, cancelled boolean NOT NULL DEFAULT false, UNIQUE(prospect_id,version));
CREATE TABLE IF NOT EXISTS events (id bigserial PRIMARY KEY, audit_id uuid REFERENCES audits(id), stage text NOT NULL, message text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS captures (id uuid PRIMARY KEY, audit_id uuid NOT NULL REFERENCES audits(id), data jsonb NOT NULL);
CREATE TABLE IF NOT EXISTS evidence (id uuid PRIMARY KEY, audit_id uuid NOT NULL REFERENCES audits(id), data jsonb NOT NULL);
CREATE TABLE IF NOT EXISTS findings (id uuid PRIMARY KEY, audit_id uuid NOT NULL REFERENCES audits(id), data jsonb NOT NULL, approval text NOT NULL DEFAULT 'PENDING' CHECK(approval IN ('PENDING','APPROVED','REJECTED','EDITED')), revision integer NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS finding_revisions (id bigserial PRIMARY KEY, finding_id uuid NOT NULL REFERENCES findings(id), revision integer NOT NULL, data jsonb NOT NULL, approval text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(finding_id,revision));
CREATE TABLE IF NOT EXISTS reports (id uuid PRIMARY KEY, audit_id uuid NOT NULL REFERENCES audits(id), version integer NOT NULL, snapshot jsonb NOT NULL, html text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(audit_id,version));
CREATE TABLE IF NOT EXISTS artifacts (id uuid PRIMARY KEY, report_id uuid NOT NULL UNIQUE REFERENCES reports(id), status text NOT NULL DEFAULT 'QUEUED', path text, error jsonb, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS outreach (id uuid PRIMARY KEY, report_id uuid NOT NULL REFERENCES reports(id), revision integer NOT NULL, data jsonb NOT NULL, exported_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(report_id,revision));
CREATE TABLE IF NOT EXISTS workers (id text PRIMARY KEY, heartbeat_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS login_attempts (id integer PRIMARY KEY CHECK(id=1), failures integer NOT NULL DEFAULT 0, reset_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS evidence_audit ON evidence(audit_id);
CREATE INDEX IF NOT EXISTS events_audit ON events(audit_id,id);
CREATE INDEX IF NOT EXISTS findings_audit ON findings(audit_id);
CREATE OR REPLACE FUNCTION reject_immutable_mutation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Immutable history'; END $$;
DROP TRIGGER IF EXISTS immutable_report ON reports;
CREATE TRIGGER immutable_report BEFORE UPDATE OR DELETE ON reports FOR EACH ROW EXECUTE FUNCTION reject_immutable_mutation();
DROP TRIGGER IF EXISTS immutable_evidence ON evidence;
CREATE TRIGGER immutable_evidence BEFORE UPDATE OR DELETE ON evidence FOR EACH ROW EXECUTE FUNCTION reject_immutable_mutation();
DROP TRIGGER IF EXISTS immutable_capture ON captures;
CREATE TRIGGER immutable_capture BEFORE UPDATE OR DELETE ON captures FOR EACH ROW EXECUTE FUNCTION reject_immutable_mutation();
DROP TRIGGER IF EXISTS immutable_revision ON finding_revisions;
CREATE TRIGGER immutable_revision BEFORE UPDATE OR DELETE ON finding_revisions FOR EACH ROW EXECUTE FUNCTION reject_immutable_mutation();
INSERT INTO migrations(version) VALUES(1) ON CONFLICT DO NOTHING;
